"""FM-16O original six-stage editorial pathways."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
h,k,t,u,w,c=s.symbols('h k t u w c',real=True)
PATHS={'det-classification':'MAT.singular.classify','inverse-systems':'MAT.systems.inverse','plane-normal':'VEC.plane.normal','cross-order':'VEC.vector-properties.order'}
RATIONALES={
'det-classification':['Calculate a signed determinant prerequisite.','Distinguish singularity from zero matrix.','Classify several square matrices by determinants.','Relate determinants of products and inverse existence.','Infer singular parameter values and classify a second matrix simultaneously.','Classify two related 3 by 3 matrices across a two-parameter plane; prove completeness.'],
'inverse-systems':['Solve a scalar equation.','Explain why an inverse method needs nonsingularity.','Solve a fully specified system by inverse.','Translate a system with three unknowns to matrix form and verify.','Recover an unknown right-hand side using an extra solution constraint.','Classify all systems in a family using inverse where valid and elimination at singular values.'],
'plane-normal':['Read components and calculate dot product.','Explain nonzero normal and scaling invariance.','Identify which candidate is normal using two direction vectors.','Recover a normal from points and construct plane.','Find a normal with prescribed component and check incidence.','Classify all normalized-by-component normals when directions vary, including when they fail to define a plane.'],
'cross-order':['Recall signed arithmetic.','Diagnose reversal of cross-product order.','Use anti-commutativity to evaluate a reversed product.','Establish a triangle normal using cyclic edge order.','Recover a vector from a reversed cross-product and a specified component.','Combine anti-commutativity with fixed length and classify all possible vectors.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;d=2*v+5
 if path=='det-classification':
  A=M([[a,1],[b,d]])
  if l==1:
   f=[A.det()];q=f'Calculate the signed determinant of {L(A)}.';ans=L(f[0]);steps=[f'Multiply the main diagonal and subtract the other diagonal product: {a} times {d} minus {b} = {ans}.'];hints=['Use the two diagonal products.','Subtract in the correct order.'];mistake='Adding the diagonal products.'
  elif l==2:
   B=M([[a,b],[2*a,2*b]]);f=[B.det(),False];q=f'A student says {L(B)} must be invertible because none of its entries is zero. Explain the error.';ans='Singular, despite all entries being nonzero.';steps=['The second row is twice the first; the rows are dependent.',f'The determinant is {L(B.det())}. Invertibility depends on a nonzero determinant, not nonzero entries.'];hints=['Compare the rows.','Use the determinant criterion.'];mistake='Confusing nonzero entries with a nonzero determinant.'
  elif l==3:
   B=M([[a,1,b],[0,b,d],[a,1,b]]);C=M([[a,1,0],[1,b,1],[0,1,d]]);f=[A.det(),B.det(),C.det()];q=f'Use determinants to classify A={L(A)}, B={L(B)} and C={L(C)} as singular or nonsingular.';ans=f'A and C nonsingular; B singular. Determinants {L(f[0])}, 0, {L(f[2])}.';steps=[f'For A the determinant is {L(f[0])}, nonzero.', 'For B the first and third rows coincide, so its determinant is zero.',f'Expand C along the first row: {a}({b} times {d}-1)-{d}={L(f[2])}, nonzero.'];hints=['Use row equality to simplify B.','Expand C along a row with a zero.'];mistake='Assuming a matrix containing a zero entry is singular.'
  elif l==4:
   B=M([[1,b],[0,d]]);C=M([[a,1],[2*a,2]]);f=[(A*B).det(),(A*C).det(),True,False];q=f'Given A={L(A)}, B={L(B)}, C={L(C)}, determine whether AB and AC have inverses without multiplying the matrices. Explain whether reversing the products changes singularity.';ans=f'AB and BA nonsingular, AC and CA singular; product determinants {L(f[0])} and 0.';steps=[f'The determinants of A,B,C are {L(A.det())}, {d}, 0 respectively.',f'Using determinant multiplicativity, det(AB)={L(f[0])} and det(AC)=0.', 'The determinant products are unchanged on reversing order, although the matrices need not be equal. Thus the same classifications hold.'];hints=['Calculate individual determinants.','Use det(PQ)=det(P)det(Q).'];mistake='Assuming reversed products are equal as matrices.'
  elif l==5:
   B=M([[k,a],[b,k]]);C=M([[k,a],[b,-k]]);r=s.sqrt(a*b);f=[-r,r,C.det()];q=f'For B={L(B)} and C={L(C)}, find every real k for which exactly one matrix is singular. Identify which matrix is invertible at each solution.';ans=f'k={L(-r)} or {L(r)}; B singular and C invertible.';steps=[f'det(B)={L(B.det())}, det(C)={L(C.det())}.',f'det(C) is strictly negative for all real k because {a*b}>0.',f'det(B)=0 iff k={L(-r)} or {L(r)}. At either value det(C)={-2*a*b}, so C is invertible.'];hints=['Calculate both determinants.','Decide whether either determinant can never vanish.'];mistake='Discarding the negative square-root solution.'
  else:
   B=M([[a,1,0],[0,k,b],[0,h,k]]);C=M([[a,1,0],[0,k,b],[0,h,k-d]]);f=[B.det(),C.det(),k*k/b,k*(k-d)/b,0];q=f'For all real k,h classify B={L(B)} and C={L(C)} as both singular, only B singular, only C singular, or neither singular. Give exact parameter conditions and prove completeness.';ans=f'Both singular only (k,h)=(0,0); only B on h={L(k*k/b)} with k nonzero; only C on h={L(k*(k-d)/b)} with k nonzero; neither elsewhere.';steps=[f'Expand along the first column to obtain det(B)={L(B.det())} and det(C)={L(C.det())}.',f'B is singular exactly when h={L(k*k/b)}; C exactly when h={L(k*(k-d)/b)}.',f'Both equations hold only if {d}k=0, forcing k=h=0.', 'On either curve away from the origin exactly its corresponding determinant vanishes. Outside both curves neither determinant vanishes.', 'Every pair belongs to precisely one of these four cases, and the determinant criterion is necessary and sufficient.'];hints=['Use first-column expansion.','Compare the two zero-determinant curves, then partition their union and complement.'];mistake='Treating one singular determinant as sufficient for both.'
 elif path=='inverse-systems':
  A=M([[a,1],[1,b]]);P=M([d,-a]);B=A*P
  if l==1:
   f=[s.Rational(d,a)];q=f'Solve {a}x={d} by multiplying by the reciprocal of {a}.';ans=L(f[0]);steps=[f'The nonzero coefficient has reciprocal {L(s.Rational(1,a))}; multiply both sides to get {ans}.'];hints=['The reciprocal is defined.','Multiply both sides.'];mistake='Multiplying by the coefficient instead of its reciprocal.'
  elif l==2:
   C=M([[1,a],[2,2*a]]);Y=M([b,2*b]);f=[C.det(),False];q=f'A student proposes X=C^(-1)Y for C={L(C)} and Y={L(Y)}. Explain why the method fails and whether the system can still have solutions.';ans='No inverse exists; infinitely many solutions.';steps=['The second row is twice the first, so det(C)=0 and an inverse cannot be used.',f'The equations both reduce to x+{a}y={b}. Every real y gives x={b}-{a}y, so solutions still exist.'];hints=['Compare the rows.','Check the right-hand sides too.'];mistake='Assuming a singular coefficient matrix implies inconsistency.'
  elif l==3:
   f=[A.inv(),P];q=f'Use an inverse matrix to solve AX=B with A={L(A)} and B={L(B)}. Verify the solution.';ans=L(P);steps=[f'det(A)={A.det()} is nonzero; A inverse is {L(A.inv())}.',f'Multiply A inverse by B to obtain X={ans}.',f'Check AX={L(B)}.'];hints=['Find the determinant and inverse.','Multiply the inverse on the left.'];mistake='Applying the inverse to the wrong side.'
  elif l==4:
   C=M([[a,1,0],[1,b,1],[0,1,d]]);Y=M([1,-a,b]);Z=C*Y;f=[C.inv(),Y];q=f'Use matrix inversion to solve the simultaneous equations {a}x+y={Z[0]}, x+{b}y+z={Z[1]}, y+{d}z={Z[2]}. Verify all three equations.';ans=L(Y);steps=[f'Collect the coefficients into C={L(C)} and the constants into {L(Z)}.',f'det(C)={C.det()} is nonzero. Cofactor inversion gives {L(C.inv())}.',f'Multiply this inverse by the constants to obtain (x,y,z)^T={ans}.',f'Substitute into all three original equations to recover {L(Z)}.'];hints=['Write CX=Z first.','Use the transpose of the cofactor matrix divided by the determinant.'];mistake='Misaligning coefficients or using the cofactor matrix without transposing.'
  elif l==5:
   Y=M([d,k]);X=A.inv()*Y;K=s.solve(X[0]+X[1]-a,k)[0];F=X.subs(k,K);f=[K,F];q=f'Let A={L(A)} and AX={L(Y)}. The two components of X sum to {a}. Use the inverse to determine k and X, and justify uniqueness.';ans=f'k={L(K)}, X={L(F)}.';steps=[f'The inverse exists because det(A)={A.det()}. Multiplication gives X={L(X)}.',f'Set the sum of the components equal to {a}: {L(s.factor(X[0]+X[1]))}={a}.',f'This linear equation has nonzero coefficient and gives k={L(K)}. Substitute to obtain {L(F)}; it satisfies both conditions.'];hints=['Keep the right-hand side symbolic.','Impose the extra sum constraint on the solution.'];mistake='Setting the sum of the constants equal to the sum of the unknowns.'
  else:
   C=M([[a,1],[k,b]]);Y=M([d,h]);X=C.inv()*Y;pole=a*b;threshold=b*d;f=[X,pole,threshold,M([t,d-a*t])];q=f'For every real k,h, solve CX=Y with C={L(C)} and Y={L(Y)}. Use the inverse wherever possible. At singular values classify the solution set and give all solutions, proving completeness.';ans=f'For k not equal to {pole}, X={L(X.applyfunc(s.factor))}; for k={pole}, h={threshold} gives X={L(M([t,d-a*t]))}, t real; otherwise no solution.';steps=[f'det(C)={L(C.det())}, so the inverse exists precisely when k differs from {pole}.',f'For those k, C inverse times Y gives X={L(X.applyfunc(s.factor))}; it is unique.',f'At k={pole} the second row is {b} times the first. Consistency requires h={threshold}.',f'If consistent, choose x=t and use the first equation to force y={d}-{a}t. Otherwise the equations contradict.', 'The singular and nonsingular cases exhaust all parameters, and substitution verifies the displayed solution families.'];hints=['Find the determinant before inverting.','When it vanishes, compare the two original equations rather than dividing by zero.'];mistake='Using the inverse formula at the singular parameter.'
 elif path=='plane-normal':
  U=M([a,1,0]);V=M([0,b,1]);N=U.cross(V);P=M([1,2,3])
  if l==1:
   f=[U.dot(V)];q=f'Calculate the scalar product of {L(U)} and {L(V)}.';ans=L(f[0]);steps=[f'Multiply matching components and add: 0+{b}+0={ans}.'];hints=['Pair each coordinate.','Add all three products.'];mistake='Using vector magnitudes instead of component products.'
  elif l==2:
   f=[True,False];q=f'A plane has nonzero normal n={L(N)}. A student says -2n is not a normal and the zero vector is also a valid normal. Explain both errors.';ans='-2n is a valid normal; the zero vector is not.';steps=['Any nonzero scalar multiple of a normal is perpendicular to the same directions.', 'The zero vector has no direction and cannot specify a plane normal.'];hints=['Normal direction can be reversed.','Distinguish zero dot product from a valid direction.'];mistake='Treating the normal as unique or allowing zero.'
  elif l==3:
   W=N+M([0,1,0]);f=[N.dot(U),N.dot(V),W.dot(U),W.dot(V)];q=f'A plane has independent directions {L(U)} and {L(V)}. Which of {L(N)} and {L(W)} is a normal? Use scalar products.';ans=f'Only {L(N)}.';steps=[f'The first candidate has dot products {f[0]} and {f[1]} with the directions.',f'The second has dot products {f[2]} and {f[3]}.', 'A nonzero normal must be perpendicular to both independent directions; only the first candidate qualifies.'];hints=['Test each candidate against both directions.','Both dot products must vanish.'];mistake='Checking perpendicularity against just one direction.'
  elif l==4:
   Q=P+U;R=P+V;f=[N,N.dot(P)];q=f'Find a normal with first component 1 for the plane through P={L(P)}, Q={L(Q)}, R={L(R)}. Obtain its Cartesian equation.';ans=f'n={L(N)}, n dot r={L(N.dot(P))}.';steps=[f'Form PQ={L(U)} and PR={L(V)}.',f'Their cross product is {L(N)}, already with first component 1 and nonzero.',f'Using P, the plane equation is x-{a}y+{a*b}z={N.dot(P)}. Substitution of Q and R gives the same constant.'];hints=['Subtract position vectors.','Use a cross product and a known point.'];mistake='Crossing position vectors rather than displacements.'
  elif l==5:
   W=d*N;Q=P+U+V;f=[W,W.dot(P),True];q=f'A plane through P={L(P)} has directions {L(U)} and {L(V)}. Its normal has first component {d}. Find that normal without a cross product, and determine whether Q={L(Q)} lies on the plane.';ans=f'n={L(W)}; Q lies on the plane.';steps=[f'Write n=({d},y,z). The perpendicularity conditions give {a*d}+y=0 and {b}y+z=0.',f'Thus n={L(W)}, nonzero, and the two equations force uniqueness.',f'The plane constant is {W.dot(P)}; n dot Q={W.dot(Q)}, so Q lies on the plane.'];hints=['Set both dot products to zero.','Then compare the dot products of the two position vectors.'];mistake='Assuming the given first component is the normal magnitude.'
  else:
   U=M([a,1,0]);V=M([h,k,b*k]);Z=M([1,-a,(a*k-h)/(b*k)]);f=[Z,-a,M([1,-a,t]),0];q=f'For all real h,k, consider directions u={L(U)} and v={L(V)}. Classify all vectors n with first component 1 perpendicular to both. In each case decide whether u,v themselves specify two independent plane directions, and justify all cases.';ans=f'For k nonzero, unique n={L(Z)} and independent directions; for k=0,h nonzero, no such n but independent directions; for h=k=0, n={L(M([1,-a,t]))}, t real, and no two independent directions.';steps=[f'Write n=(1,y,z). The first dot product forces y=-{a}.',f'The second condition becomes h-{a}k+{b}kz=0. If k is nonzero it forces z={L(Z[2])}; the third component of v is nonzero so v cannot be parallel to u.',f'If k=0 and h is nonzero, v=(h,0,0) is independent of u but the second dot product equals h, so no normal with first component 1 exists.',f'If h=k=0, v is zero and the second equation is automatic. All normals are {L(M([1,-a,t]))}; the directions do not span a plane.', 'These branches exhaust all real pairs; each displayed normal satisfies both equations and is nonzero.'];hints=['Use the prescribed first component before solving.','Handle the zero coefficient of z separately and test independence.'];mistake='Equating absence of a prescribed normal with absence of a plane.'
 else:
  U=M([a,0,0]);V=M([0,b,d]);N=U.cross(V)
  if l==1:
   f=[-a*b];q=f'Calculate the negative of {a} times {b}.';ans=L(f[0]);steps=[f'The product is {a*b}; negating gives {ans}.'];hints=['Multiply the positive numbers.','Reverse the sign.'];mistake='Leaving the product positive.'
  elif l==2:
   f=[-N];q=f'Given u cross v={L(N)}, a student says v cross u is unchanged. Explain the error and give v cross u.';ans=L(-N);steps=['Exchanging the factors reverses the oriented normal, not its magnitude.',f'By anti-commutativity v cross u=-(u cross v)={ans}.'];hints=['Think of the right-hand rule.','Negate every component.'];mistake='Treating the cross product as commutative.'
  elif l==3:
   f=[N,-N];q=f'Calculate u cross v for u={L(U)}, v={L(V)}, then use anti-commutativity to obtain v cross u without another determinant expansion.';ans=f'{L(N)} and {L(-N)}.';steps=[f'Expanding the component formula gives u cross v={L(N)}.',f'Negate all components for v cross u={L(-N)}.'];hints=['Use the standard cross-product component formula.','Reverse the entire vector.'];mistake='Negating only one component.'
  elif l==4:
   P=M([1,2,3]);Q=P+U;R=P+V;f=[N,N,-N];q=f'For triangle P={L(P)}, Q={L(Q)}, R={L(R)}, compute PQ cross PR, QR cross QP, and PR cross PQ. Explain which vertex orders agree in orientation.';ans=f'{L(N)}, {L(N)}, {L(-N)} respectively.';steps=[f'PQ={L(U)}, PR={L(V)}, so the first product is {L(N)}.', 'QR=v-u and QP=-u. Distribute to get (v-u) cross (-u)=-(v cross u)=u cross v.',f'Reversing the first pair gives {L(-N)}; cyclic order preserves the normal, swapping two vertices reverses it.'];hints=['Use displacements from the same vertex.','Distribute the cross product and use u cross u=0.'];mistake='Assuming changing the starting vertex always reverses orientation.'
  elif l==5:
   W=M([d,-b,-a]);Y=W.cross(U);f=[W,-Y];q=f'Let u={L(U)} and w=(x,y,z). Given w cross u={L(Y)} and x={d}, recover w and calculate u cross w. Prove uniqueness.';ans=f'w={L(W)}; u cross w={L(-Y)}.';steps=[f'Expanding w cross u gives (0,{a}z,-{a}y).',f'Equate the last two components to {Y[1]} and {Y[2]}, forcing z={-a}, y={-b}. The first component of w is given.',f'Thus w={L(W)} and reversal gives u cross w={L(-Y)}. Every component is determined.'];hints=['Keep the order w cross u when expanding.','The given x fixes the component not determined by the cross product.'];mistake='Solving with u cross w instead of w cross u.'
  else:
   U=M([a,b,0]);V=M([1,0,0]);R=s.sqrt(c*c-b*b);F=M([R,-b,0]);G=M([-R,-b,0]);f=[F,G,b];q=f'Let u={L(U)} and v={L(V)}. For each real C, find all vectors w satisfying v cross w=u cross v and |w|=C. Classify the number of solutions, explicitly consider impossible lengths, and prove completeness.';ans=f'C<{b}: no solutions; C={b}: one; C>{b}: two, w=(±sqrt(C^2-{b*b}),-{b},0).';steps=['Anti-commutativity gives u cross v=-(v cross u), so v cross (w+u)=0.',f'Because v=(1,0,0), w+u must be a scalar multiple of v. This forces w=(x,-{b},0), x arbitrary.',f'A magnitude is nonnegative and |w| squared=x^2+{b*b}. The smallest attainable length is {b}.',f'For C at least {b}, x^2=C^2-{b*b}; equality gives one root, larger C two opposite roots.', 'Each displayed vector satisfies the original cross-product equation and length condition. The component constraints and real square-root cases exhaust every possibility.'];hints=['Reverse one cross product and factor by distributivity.','Use the fixed transverse components to solve the length constraint.'];mistake='Missing the sign reversal or accepting a negative target length after squaring.'
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
